#include <stdio.h>

void change(int n)   /* 递归函数：把十进制转二进制 */
{
    if (n == 0)      /* 递归出口：n 等于 0 就停止 */
    {
        return;
    }
    change(n / 2);
    printf("%d", n % 2);
}

int main()
{
    int num;
    printf("请输入正整数：");
    scanf("%d", &num);
    printf("二进制结果：");
    change(num);
    return 0;
}
